// Package generated holds calls in generated files, which neither side judges, beside the same calls in a file
// written by hand, and the two files whose line directives point across: a generated file whose directive moves a
// call into a hand-written Go file, still judged generated by the name it was parsed from, and a hand-written file
// whose directive moves a call into the generated one, still judged.
package generated

import "encoding/json"

type hidden struct{ value int }

func byHand() {
	json.Marshal(hidden{})
	json.Marshal(&hidden{})
}
